def comps(G):
    H=len(G); W=len(G[0]); seen=set(); out=[]
    for r in range(H):
        for c in range(W):
            if (r,c) not in seen:
                col=G[r][c]; stack=[(r,c)]; cells=[]
                while stack:
                    a,b=stack.pop()
                    if (a,b) in seen: continue
                    seen.add((a,b)); cells.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and G[x][y]==col and (x,y) not in seen:
                            stack.append((x,y))
                rs=[a for a,b in cells]; cs=[b for a,b in cells]
                out.append((col,len(cells),min(rs),min(cs),tuple(sorted((a-min(rs),b-min(cs)) for a,b in cells))))
    return out
