def canon(shp):
    best=None
    cur=[(a,b) for a,b in shp]
    for _ in range(4):
        for s in (cur,[(a,-b) for a,b in cur]):
            mr=min(a for a,b in s); mc=min(b for a,b in s)
            c=tuple(sorted((a-mr,b-mc) for a,b in s))
            if best is None or c<best: best=c
        cur=[(b,-a) for a,b in cur]
    return best
